src/graph_actions.py:
"""Transactional reference-search actions, independent of a learned policy."""
import copy
import math
from typed_cell import CellType, VerticalScope
from shared_modules import infer


def apply_action(graph, action, require_access=False):
    """Apply one move or joint role change; rollback incompatible assignments.

    Adding a node requires an existing construction anchor. This is the public
    growth interface; BuildingGraph.add_node remains a low-level fixture helper.
    """
    old=copy.deepcopy(graph.__dict__)
    try:
        kind=action['kind']
        if kind=='attach':
            anchor=graph.nodes[action['anchor']]
            if action['id'] in graph.nodes: raise ValueError('duplicate occurrence id')
            x,y=float(action['x']),float(action['y'])
            if not math.isfinite(x) or not math.isfinite(y): raise ValueError('nonfinite pose')
            graph.add_node(action['id'],x,y,floor_index=anchor.floor_index,
                scope=VerticalScope(action.get('scope','independent')),
                cell_type=CellType(action.get('function','room')))
            graph.add_edge(action['id'],anchor.node_id,properties={'relation':'construction','validated':False})
        elif kind=='reassign':
            graph.reassign_functions(action['functions'],require_access=require_access)
        elif kind=='pose':
            node=graph.nodes[action['id']]; root=node.metadata.get('root_id',node.node_id)
            x,y=float(action['x']),float(action['y'])
            if not math.isfinite(x) or not math.isfinite(y): raise ValueError('nonfinite pose')
            for n in graph.nodes.values():
                if n.node_id==root or n.metadata.get('root_id')==root:
                    n.x=x;n.y=y
        else: raise ValueError('unknown graph action')
        solution=infer(graph)
        if solution.unresolved: raise ValueError(str(solution.unresolved))
        if require_access and not graph.validate_circulation_connectivity():
            raise ValueError('same-floor access disconnected')
        return solution
    except Exception:
        graph.__dict__.clear();graph.__dict__.update(old)
        raise

src/graph_continuity.py:
"""Local floor-plate continuity certificates on implicit convex boundaries.

No polygon construction, clipping, Boolean overlay, or final-layout rejection.
For a hole-free connected floor plate, attaching a convex room cannot create a
hole if its intersection with the old plate is one connected boundary arc.
Shared-shape shrinkage must additionally preserve all old multi-room junctions.
The dictionary maintains those junction witnesses transactionally.
"""
import math

TOLERANCE=1e-6


def protected_hull(points):
    """Extreme junction witnesses, not a realized room/floor polygon."""
    points=sorted(set(points))
    if len(points)<=2:return tuple(points)
    def cross(a,b,c):return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    lower=[];upper=[]
    for p in points:
        while len(lower)>=2 and cross(lower[-2],lower[-1],p)<=0:lower.pop()
        lower.append(p)
    for p in reversed(points):
        while len(upper)>=2 and cross(upper[-2],upper[-1],p)<=0:upper.pop()
        upper.append(p)
    return tuple(lower[:-1]+upper[:-1])


def boundary_data(shape):
    cache=shape.continuity_cache
    if 'boundary' not in cache:
        start=0.;rows=[]
        for face in shape.faces:
            angle,nx,ny,b,cx,cy,tx,ty,lo,hi=face
            rows.append((face,start));start+=hi-lo
        cache['boundary']=(rows,start)
    return cache['boundary']


def boundary_interval(shape,key):
    """Intersection with a supporting line, retaining point-only contacts too."""
    cache=shape.continuity_cache;token=('line',key)
    if token in cache:return cache[token]
    length=math.hypot(*key[:2]);nx,ny=key[0]/length,key[1]/length;b=key[2]/length
    cx,cy=nx*b,ny*b;tx,ty=-ny,nx;lo=-math.inf;hi=math.inf
    for _,fx,fy,bound,*_ in shape.faces:
        coefficient=fx*tx+fy*ty;residual=bound-fx*cx-fy*cy
        if abs(coefficient)<1e-10:
            if residual < -TOLERANCE:lo=math.inf;break
        elif coefficient>0:hi=min(hi,(residual+TOLERANCE)/coefficient)
        else:lo=max(lo,(residual+TOLERANCE)/coefficient)
    found=None
    if math.isfinite(lo) and math.isfinite(hi) and lo<=hi+1e-7:
        found=(lo,hi) if lo<=hi else ((lo+hi)/2,)*2
    cache[token]=found
    return found


def point_inside(shape,point,tolerance=TOLERANCE):
    x,y=point
    return all(nx*x+ny*y<=b+tolerance for _,nx,ny,b,*_ in shape.faces)


def arc_position(shape,key,value):
    """Map a support-line coordinate onto the perimeter's circular coordinate."""
    rows,total=boundary_data(shape)
    length=math.hypot(*key[:2]);nx,ny=key[0]/length,key[1]/length;b=key[2]/length
    point=(nx*b-ny*value,ny*b+nx*value)
    for face,start in rows:
        _,fx,fy,bound,cx,cy,tx,ty,lo,hi=face
        if abs(fx-nx)<1e-7 and abs(fy-ny)<1e-7 and abs(bound-b)<1e-7:
            tangent=tx*point[0]+ty*point[1]
            if lo-2*TOLERANCE<=tangent<=hi+2*TOLERANCE:
                tangent=min(hi,max(lo,tangent))
                return start+tangent-lo,(cx+tx*tangent,cy+ty*tangent)
    # A vertex can touch another cell without a positive-length facet on this
    # line. Omitting it would miss a hole closed by a corner-only contact.
    best=None
    for face,start in rows:
        _,_,_,_,cx,cy,tx,ty,lo,hi=face
        for value,coordinate in ((lo,start),(hi,start+hi-lo)):
            error=(cx+tx*value-point[0])**2+(cy+ty*value-point[1])**2
            if best is None or error<best[0]:best=(error,coordinate)
    if best is not None and best[0] <= (2*TOLERANCE)**2:return best[1],point
    return None


def connected_contact_arc(intervals,perimeter,tolerance=TOLERANCE):
    """True for one connected arc, including a wrap across the canonical seam."""
    if not intervals:return False
    merged=[]
    pieces=[]
    for lo,hi in intervals:
        if lo>hi+tolerance:pieces.extend(((lo,perimeter),(0.,hi)))
        else:pieces.append((min(lo,hi),max(lo,hi)))
    for lo,hi in sorted(pieces):
        if merged and lo<=merged[-1][1]+tolerance:merged[-1][1]=max(merged[-1][1],hi)
        else:merged.append([lo,hi])
    components=len(merged)
    if components>1 and merged[0][0]+perimeter-merged[-1][1]<=tolerance:components-=1
    return components==1


def junctions_from_contacts(contacts,perimeter,tolerance=TOLERANCE):
    """New local junction points and the existing rooms meeting at each one."""
    endpoints=[]
    for nid,lo,hi,p,q in contacts:
        endpoints.extend(((lo,nid,p),(hi,nid,q)))
    groups=[]
    for item in sorted(endpoints,key=lambda row:row[0]):
        if groups and item[0]-groups[-1][-1][0]<=tolerance:groups[-1].append(item)
        else:groups.append([item])
    if len(groups)>1 and groups[0][0][0]+perimeter-groups[-1][-1][0]<=tolerance:
        groups[0]=groups.pop()+groups[0]
    result=[]
    for group in groups:
        neighbors=frozenset(row[1] for row in group)
        if len(neighbors)>=2:
            point=(sum(row[2][0] for row in group)/len(group),sum(row[2][1] for row in group)/len(group))
            result.append((point,neighbors))
    return result

src/graph_proxy.py:
"""Graph-only growth estimates. No polygon construction, clipping or GEOS.

Live generation reads the shared implicit dictionary. The legacy standalone
star sketch remains provisional. Physical validity is independently audited
on explicit preview or inference completion.
"""
from collections import Counter, defaultdict
from functools import lru_cache
import math


def root_id(n): return n.metadata.get('root_id',n.node_id)


def site_net_area(site):
    """Exact available polygon area; never substitute raster cell counts."""
    if site.get('exactArea') is not None:return float(site['exactArea'])
    def area(loop):
        pts=[(p['x'],p['y']) if isinstance(p,dict) else p for p in loop]
        return abs(math.fsum(x*v-y*u for (x,y),(u,v) in zip(pts,pts[1:]+pts[:1])))/2
    if not site.get('outer'):raise ValueError('site has no exact area or boundary')
    return area(site['outer'])-math.fsum(area(h) for h in site.get('holes',()))


def origin_fits(point,boundary,holes=(),radius=4.5):
    """Conservative scalar site certificate for every radius-bounded prototype."""
    from graph_sampler import GraphSeedSampler
    from typed_cell import BuildingGraph
    boundary=[(p['x'],p['y']) if isinstance(p,dict) else p for p in boundary]
    if not GraphSeedSampler._point_inside_polygon(point,boundary,setback=radius):return False
    for hole in holes:
        hole=[(p['x'],p['y']) if isinstance(p,dict) else p for p in hole]
        if GraphSeedSampler._point_inside_polygon(point,hole):return False
        if BuildingGraph._min_distance_to_boundary(point,hole)<radius:return False
    return True


class SpatialNodes:
    def __init__(self,graph,radius=4.5):
        self.radius=radius;self.width=2*radius;self.cells=defaultdict(list)
        for n in graph.nodes.values():self.cells[self.key(n.floor_index,n.x,n.y)].append(n)

    def key(self,f,x,y):return (f,math.floor(x/self.width),math.floor(y/self.width))

    def near(self,f,x,y):
        _,gx,gy=self.key(f,x,y)
        return [n for dx in (-1,0,1) for dy in (-1,0,1) for n in self.cells.get((f,gx+dx,gy+dy),())
                if (n.x-x)**2+(n.y-y)**2 <= self.width**2+1e-8]


def contact_length(a,b,others,radius):
    """Scalar bisector interval from embedded graph coordinates, no room vertices."""
    return constraint_contact(a,b,[(x-a[0],y-a[1]) for x,y in others if math.dist((x,y),a)>1e-8],
        [(x-b[0],y-b[1]) for x,y in others if math.dist((x,y),b)>1e-8],radius)


def constraint_contact(a,b,a_vectors,b_vectors,radius):
    """Shared bisector interval under both occurrences' pooled half-space evidence."""
    dx,dy=b[0]-a[0],b[1]-a[1];d=math.hypot(dx,dy)
    if d<1e-8 or d>=2*radius:return 0.
    tx,ty=-dy/d,dx/d;mx,my=(a[0]+b[0])/2,(a[1]+b[1])/2
    upper=math.sqrt(max(0.,radius**2-d*d/4));lower=-upper
    for (bx,by),vectors in ((a,a_vectors),(b,b_vectors)):
        for vx,vy in vectors:
            coefficient=2*(vx*tx+vy*ty)
            bound=vx*vx+vy*vy-2*(vx*(mx-bx)+vy*(my-by))
            if abs(coefficient)<1e-10:
                if bound < -1e-8:return 0.
            elif coefficient>0:upper=min(upper,bound/coefficient)
            else:lower=max(lower,bound/coefficient)
            if upper-lower<=0:return 0.
    return max(0.,upper-lower)


def refresh_local_contacts(graph,new_ids,radius,min_contact=.5):
    sketch=GraphSketch(graph)
    contact_radius=radius*math.cos(math.pi/getattr(sketch.prior,'directions',64))
    spatial=sketch.spatial
    affected=set(new_ids)
    for nid in new_ids:
        n=graph.nodes[nid];affected.update(p.node_id for p in spatial.near(n.floor_index,n.x,n.y))
    # A full-height footprint changes on every floor when any floor adds evidence.
    roots={root_id(graph.nodes[nid]) for nid in affected}
    affected={n.node_id for n in graph.nodes.values() if root_id(n) in roots}
    pairs=set()
    for nid in affected:
        n=graph.nodes[nid]
        for m in spatial.near(n.floor_index,n.x,n.y):
            if m.node_id!=nid:pairs.add(tuple(sorted((nid,m.node_id))))
    keep=[]
    # Recompute affected local contact intents; graph changes can occlude old edges.
    for edge in graph.edges_horiz:
        if edge.u not in affected and edge.v not in affected:keep.append(edge)
    graph.edges_horiz=keep
    graph._adj_horiz={nid:set() for nid in graph.nodes}
    for edge in keep:
        graph._adj_horiz[edge.u].add(edge.v);graph._adj_horiz[edge.v].add(edge.u)
    for u,v in sorted(pairs):
        a,b=graph.nodes[u],graph.nodes[v]
        length=constraint_contact((a.x,a.y),(b.x,b.y),sketch.vectors[root_id(a)],
                                  sketch.vectors[root_id(b)],contact_radius)
        if length>=min_contact:
            graph.add_edge(u,v,shared_length=length,properties={'relation':'construction','validated':False})


def star_signature(vectors):
    """Rotation-only quantized star descriptor. A hypothesis, never proof of reuse."""
    return _star_signature(tuple(sorted(vectors)))


@lru_cache(maxsize=32768)
def _star_signature(vectors):
    if not vectors:return ()
    arms=[(math.hypot(x,y),math.atan2(y,x)) for x,y in vectors]
    return min(tuple(sorted((round(d/.1),round(((a-base)%(2*math.pi))/.017453292519943295)) for d,a in arms))
               for _,base in arms)


def radial_area(vectors,radius,samples=24):
    """Scalar angular quadrature of distance constraints, with no polygon output."""
    return _radial_area(tuple(sorted(vectors)),radius,samples)


@lru_cache(maxsize=32768)
def _radial_area(vectors,radius,samples):
    arms=[(math.hypot(x,y),math.atan2(y,x)) for x,y in vectors]
    frames=[(tuple(sorted((round(d,9),round((angle-base)%(2*math.pi),9))
                          for d,angle in arms)),base) for _,base in arms]
    signature=min((sig for sig,base in frames),default=())
    bases=[base for sig,base in frames if sig==signature] or [0.]
    total=0.
    for base in bases:
        for i in range(samples):
            angle=base+2*math.pi*(i+.5)/samples;ux,uy=math.cos(angle),math.sin(angle)
            r=radius
            for x,y in vectors:
                projection=x*ux+y*uy
                if projection>1e-9:r=min(r,(x*x+y*y)/(2*projection))
            total+=r*r
    return math.pi*total/(samples*len(bases))


class GraphSketch:
    def __init__(self,graph):
        if getattr(graph,'module_bank',None) is not None:
            self.__dict__.update(graph.module_bank.view())
            return
        self.graph=graph;self.prior=getattr(graph,'size_prior',None)
        self.radius=getattr(self.prior,'radius',4.5)
        self.spatial=SpatialNodes(graph,self.radius)
        self.groups=defaultdict(list)
        for n in graph.nodes.values():self.groups[root_id(n)].append(n)
        self.signatures={};self.areas={};self.node_labels={};self.vectors={}
        self.prototypes={}
        for oid,nodes in self.groups.items():
            nearby=[]
            for n in nodes:
                nearby.extend((m.x-n.x,m.y-n.y) for m in self.spatial.near(n.floor_index,n.x,n.y)
                              if root_id(m)!=oid)
            nearby=list(dict.fromkeys(nearby))
            self.vectors[oid]=nearby
            signature=star_signature(nearby)
            label=self.signatures.setdefault(signature,f'estimate_{len(self.signatures)+1}')
            estimate=radial_area(nearby,self.radius)
            self.areas[oid]=estimate
            self.prototypes.setdefault(label,[]).append(oid)
            for n in nodes:
                n.area=estimate
                self.node_labels[n.node_id]=label
        self.constraints_valid={}
        bounds=getattr(graph,'site_boundaries',{})
        cache=getattr(graph,'_origin_fit_cache',{})
        graph._origin_fit_cache=cache
        for floor,boundary in bounds.items():
            floor_nodes=[n for n in graph.nodes.values() if n.floor_index==floor]
            holes=getattr(graph,'site_holes',{}).get(floor,[])
            for n in floor_nodes:
                key=(floor,n.x,n.y,self.radius)
                if key not in cache:cache[key]=origin_fits((n.x,n.y),boundary,holes,self.radius)
            self.constraints_valid[floor]=all(cache[(floor,n.x,n.y,self.radius)] and
                getattr(self.prior,'min_area',1.)<=self.areas[root_id(n)]<=getattr(self.prior,'max_area',80.)
                for n in floor_nodes)
        self.built=[oid for oid,nodes in self.groups.items() if nodes[0].cell_type.value!='void']
        self.counts=Counter(self.node_labels[self.groups[oid][0].node_id] for oid in self.built)

    def addition_feasible(self,x,y,floors,min_distance=2.5):
        near={f:self.spatial.near(f,x,y) for f in floors}
        if any(math.hypot(n.x-x,n.y-y)<min_distance for nodes in near.values() for n in nodes):return False
        candidate=list(dict.fromkeys((n.x-x,n.y-y) for nodes in near.values() for n in nodes))
        changed={root_id(n):list(self.vectors[root_id(n)])+[(x-n.x,y-n.y)]
                 for nodes in near.values() for n in nodes}
        lo=getattr(self.prior,'min_area',1.);hi=getattr(self.prior,'max_area',80.)
        for vectors in [candidate,*changed.values()]:
            inner=min([self.radius]+[math.hypot(x,y)/2 for x,y in vectors])
            # Every half-space contains this disk; no area quadrature is needed
            # to prove the default minimum/maximum size constraints.
            if math.pi*inner*inner>=lo and math.pi*self.radius*self.radius<=hi:continue
            if not lo<=radial_area(vectors,self.radius)<=hi:return False
        return all(any(constraint_contact((x,y),(n.x,n.y),candidate,changed[root_id(n)],self.radius*math.cos(math.pi/getattr(self.prior,'directions',64)))
                       >=getattr(self.prior,'min_contact',.5) for n in nodes) for nodes in near.values())

    def preview(self,floor,x,y,anchor,scope,site_area,budget):
        floors=range(self.graph.num_floors) if scope=='multi_floor' else (floor,)
        vectors=list(dict.fromkeys((n.x-x,n.y-y) for f in floors for n in self.spatial.near(f,x,y)))
        signature=star_signature(vectors)
        label=self.signatures.get(signature)
        k=len(self.counts)+(label not in self.counts)
        area=radial_area(vectors,self.radius)
        # Cheap local estimate; does not claim how other prototypes will change.
        filled=sum(self.areas[oid]*len(nodes) for oid,nodes in self.groups.items()
                   if nodes[0].cell_type.value!='void')
        multiplier=self.graph.num_floors if scope=='multi_floor' else 1
        singleton=sum(v==1 for v in self.counts.values())
        return k,singleton,filled+area*multiplier,area

    def metrics(self,floor,site_area=1000.,budget=10):
        nodes=[n for n in self.graph.nodes.values() if n.floor_index==floor]
        filled=sum(self.areas[root_id(n)] for n in nodes if n.cell_type.value!='void')
        rentable=sum(self.areas[root_id(n)] for n in nodes if n.cell_type.value=='room')
        core=sum(self.areas[root_id(n)] for n in nodes if n.cell_type.value=='core')
        bank=getattr(self.graph,'module_bank',None)
        if bank:budget=min(budget,bank.max_types)
        k=len(self.counts);singletons=sum(c==1 for c in self.counts.values())
        budget_cost=10.*(max(0,k-budget)/max(1,budget))**2
        singleton_cost=5.*singletons/max(1,len(self.built))
        ratio=filled/max(1.,site_area)
        underfill=35.*max(0.,1-ratio/.6)**2
        topology=self.graph.validate_circulation_connectivity(floor)
        reuse=sum(c for c in self.counts.values() if c>1)/max(1,len(self.built))
        # Fabricating one prototype serves its first occurrence; subsequent
        # independently placed occurrences earn reuse. Vertical copies and holes
        # are excluded, and legacy provisional stars earn no such credit.
        repeat_fraction=(len(self.built)-k)/max(1,len(self.built)) if bank else 0.
        reuse_bonus=20.*repeat_fraction
        penalty=0. if topology else 20.
        score=80*min(1.,ratio)+15*rentable/max(1.,filled)+reuse_bonus-budget_cost-singleton_cost-underfill-penalty
        return dict(instanceIdx=floor,floorIndex=floor,filledArea=filled,siteArea=site_area,
            rentableArea=rentable,coreArea=core,moduleCount=len(nodes),exposedPerimeter=0.,
            fillRatio=ratio,rentableRatio=rentable/max(1.,filled),daylightRatio=0.,envelopeDaylightRatio=0.,
            reuseRatio=reuse if bank else 0.,estimatedReuseRatio=reuse,reuseBonus=reuse_bonus,
            constructibilityScore=0.,envelopeEfficiency=0.,exteriorCorridorRatio=0.,triangleRatio=0.,
            constraintsValid=self.constraints_valid.get(floor,True),
            topologyValid=topology,topologyViolations=[] if topology else ['provisional_same_floor_access'],
            totalPartialLength=0.,deepRoomCount=0,depthPenaltyScore=0.,facadeChasmOccludedLength=0.,
            areaVariancePenalty=0.,rawScore=score+underfill,underfillPenalty=underfill,topologyPenalty=penalty,
            facadeChasmPenalty=0.,vocabSize=k,dictLimitBreach=max(0,k-budget),dictBreachPenalty=budget_cost,
            singletonPenalty=singleton_cost,score=score,estimateStatus='implicit_shared_constraints' if bank else 'graph_proxy_uncalibrated',
            moduleIdentityStatus='constraint_checked' if bank else 'provisional',sunExposure=None,daylightAccessibility=None,
            unavailableMetrics=['daylightRatio','constructibilityScore','envelopeEfficiency']+([] if bank else ['confirmedReuseRatio']),
            uncertainty=({'allModuleIdentitiesProvisional':False,'areaMethod':'support_line_integral','numericalTolerance':1e-6}
                         if bank else {'allModuleIdentitiesProvisional':True,'areaQuadratureSamples':24}),
            reuseAudit=dict(prototypeCount=k,independentOccurrences=len(self.built),
                verticalCopies=sum(len(self.groups[oid])-1 for oid in self.built),
                singletonCount=singletons,independentRepeatFraction=repeat_fraction,confirmedReuseRatio=reuse if bank else None))

src/realizer_experiments.py:
"""Frozen-graph realization and circulation experiments, independent of training.

Port inference accepts explicit wall evidence; an embedding alone does not supply
these ports. Reference-derived ports are an oracle capability test, not a learned
port predictor or evidence of better generated layouts.
"""
from collections import defaultdict
from dataclasses import replace
import math
import time

from graph_dictionary import rotate
from shared_modules import (Inference, Occurrence, Prototype, SizePrior, area,
    clip, _bounded_polygon, validate)
from typed_cell import BuildingGraph, GraphNode, CellType, VerticalScope


def xy(poly):return [(p['x'],p['y']) if isinstance(p,dict) else tuple(p) for p in poly]


def from_layout(document):
    event=document['event'];graph=BuildingGraph(len(document['sites']))
    graph.site_boundaries={f:xy(s['outer']) for f,s in enumerate(document['sites'])}
    graph.site_holes={f:[xy(h) for h in s['holes']] for f,s in enumerate(document['sites'])}
    occurrences={};prototypes={};unresolved={}
    for p in event['placements']:
        oid=p.get('moduleStackId',p['id']);pid=p['moduleId'];angle=math.radians(p['rotation'])
        origin=(p['position']['x'],p['position']['y']);nid=p['node_id']
        node=GraphNode(nid,*origin,floor_index=p['floor'],cell_type=CellType(p['category']),
            scope=VerticalScope(p['scope']),module_id=pid,orientation=angle,area=p['area'],
            metadata={'root_id':oid} if nid!=oid else {})
        graph.nodes[nid]=node;graph._adj_horiz[nid]=set();graph._adj_vert[nid]=set()
        if oid not in occurrences:occurrences[oid]=Occurrence(oid,[],angle=angle,prototype=pid)
        occurrences[oid].nodes.append(node)
        local=[rotate((x-origin[0],y-origin[1]),-angle) for x,y in xy(p['poly'])]
        if pid not in prototypes:prototypes[pid]=Prototype(pid,local,[],p.get('priorBoundary',False),[])
        if oid not in prototypes[pid].members:prototypes[pid].members.append(oid)
    for e in event['graphState']['edgesHoriz']:
        if e['u'] in graph.nodes and e['v'] in graph.nodes:graph.add_edge(e['u'],e['v'])
    if event['validation'].get('unresolved'):unresolved.update(event['validation']['unresolved'])
    return Inference(occurrences,prototypes,unresolved,SizePrior(),graph)


def clean_polygon(poly,tolerance=1e-8):
    result=[]
    for p in poly:
        if not result or math.dist(result[-1],p)>tolerance:result.append(p)
    if len(result)>1 and math.dist(result[0],result[-1])<tolerance:result.pop()
    changed=True
    while changed and len(result)>3:
        changed=False
        for i,p in enumerate(result):
            a,b=result[i-1],result[(i+1)%len(result)]
            u=(p[0]-a[0],p[1]-a[1]);v=(b[0]-p[0],b[1]-p[1])
            if abs(u[0]*v[1]-u[1]*v[0])<tolerance*max(1.,math.hypot(*u)*math.hypot(*v)) and u[0]*v[0]+u[1]*v[1]>=0:
                result.pop(i);changed=True;break
    return result


def corner_metrics(poly):
    poly=clean_polygon(poly);weights=[];deviations=[]
    for i,p in enumerate(poly):
        a,b=poly[i-1],poly[(i+1)%len(poly)]
        u=(a[0]-p[0],a[1]-p[1]);v=(b[0]-p[0],b[1]-p[1])
        length=math.hypot(*u)*math.hypot(*v)
        if length<1e-14:continue
        interior=math.acos(max(-1.,min(1.,(u[0]*v[0]+u[1]*v[1])/length)))
        weights.append(math.sqrt(length));deviations.append(abs(interior-math.pi/2))
    total=sum(weights)
    return dict(corners=len(weights),weightedRightFraction=sum(w for w,d in zip(weights,deviations) if d<=math.radians(5))/max(1e-12,total),
        weightedDeviationDegrees=math.degrees(sum(w*d for w,d in zip(weights,deviations))/max(1e-12,total)))


def orthogonal_completion(solution,max_area_loss=.02):
    """Try freely oriented rectangular cuts on shared prototypes, never instances.

    This is a bounded conservative realizer baseline, NOT shape synthesis. All
    observed geometry stays inside its reference footprint, and every required
    positive-length contact must survive. Failed candidates remain counted.
    """
    from shapely.geometry import Polygon
    start=time.perf_counter();prototypes=dict(solution.prototypes);accepted=0;tested=0;contact_failures=0
    current=replace(solution,prototypes=prototypes)
    if max_area_loss==0:
        return current,dict(seconds=time.perf_counter()-start,candidates=0,contactRejected=0,
            changedPrototypes=0,maxAreaLoss=0.,method='zero_loss_control')
    by_node={n.node_id:o for o in solution.occurrences.values() for n in o.nodes}
    for pid,prototype in solution.prototypes.items():
        poly=clean_polygon(prototype.polygon);base=corner_metrics(poly)
        best=(base['weightedRightFraction'],-base['weightedDeviationDegrees'],area(poly));best_poly=poly
        walls=sorted(zip(poly,poly[1:]+poly[:1]),key=lambda ab:-math.dist(*ab))
        angles=list(dict.fromkeys(round(math.atan2(b[1]-a[1],b[0]-a[0])%(math.pi/2),10) for a,b in walls))[:8]
        # Orientations come from actual wall directions; there is no world grid.
        # A continuous refinement around the best observed direction follows.
        def attempt(theta):
            nonlocal best,best_poly,tested,contact_failures
            c,s=math.cos(theta),math.sin(theta);axes=((c,s),(-s,c))
            bounds=[max(nx*x+ny*y for x,y in poly) for nx,ny in (*axes,(-c,-s),(s,-c))]
            normals=(*axes,(-c,-s),(s,-c))
            def cut(scale):
                result=poly
                for normal,bound in zip(normals,bounds):result=clip(result,normal,bound*scale)
                return clean_polygon(result)
            lo,hi=0.,1.;minimum=area(poly)*(1-max_area_loss)
            for _ in range(24):
                mid=(lo+hi)/2
                if area(cut(mid))<minimum:lo=mid
                else:hi=mid
            candidate=cut(hi);tested+=1;metric=corner_metrics(candidate)
            score=(metric['weightedRightFraction'],-metric['weightedDeviationDegrees'],area(candidate))
            if score<=best:return metric['weightedRightFraction']
            prototypes[pid]=replace(prototype,polygon=candidate)
            polygons={}
            feasible=True
            for edge in solution.graph.edges_horiz:
                if pid not in (by_node[edge.u].prototype,by_node[edge.v].prototype):continue
                for nid in (edge.u,edge.v):
                    if nid not in polygons:polygons[nid]=Polygon(current.polygon(by_node[nid].id))
                length=polygons[edge.u].boundary.buffer(1e-6).intersection(polygons[edge.v].boundary).length
                if length<solution.prior.min_contact-1e-7:feasible=False;break
            if feasible:best=score;best_poly=candidate
            else:contact_failures+=1
            prototypes[pid]=replace(prototype,polygon=best_poly)
            return metric['weightedRightFraction'] if feasible else -1.
        for theta in angles:attempt(theta)
        if angles:
            from scipy.optimize import minimize_scalar
            index=max(range(len(angles)),key=lambda j:attempt(angles[j]))
            center=angles[index]
            minimize_scalar(lambda theta:-attempt(theta),bounds=(center-.12,center+.12),method='bounded',options={'maxiter':6})
        if best_poly!=poly:accepted+=1
        prototypes[pid]=replace(prototype,polygon=best_poly)
    return current,dict(seconds=time.perf_counter()-start,candidates=tested,contactRejected=contact_failures,
        changedPrototypes=accepted,maxAreaLoss=max_area_loss,method='bounded_shared_orthogonal_cuts')


def wall_evidence(poly):
    """Explicit canonical support planes, independent of origin-to-origin edges."""
    poly=clean_polygon(poly)
    signed=sum(x*v-y*u for (x,y),(u,v) in zip(poly,poly[1:]+poly[:1]))
    if signed<0:poly=list(reversed(poly))
    result=[]
    for a,b in zip(poly,poly[1:]+poly[:1]):
        dx,dy=b[0]-a[0],b[1]-a[1];length=math.hypot(dx,dy)
        if length>1e-10:
            normal=(dy/length,-dx/length);result.append((normal,normal[0]*a[0]+normal[1]*a[1]))
    return result


def realize_ports(graph,occurrences,evidence,prior):
    """Replaceable convex adapter: pool explicit wall/port evidence by prototype.

    Each item has prototype, local normal, local offset and optional required
    contact status. Negative offsets/origins outside a module are not supported
    by this proof of concept. Non-neighbor separation is checked independently.
    """
    constraints=defaultdict(list);required=defaultdict(list);members=defaultdict(list)
    for item in evidence:
        row=(tuple(item['normal']),float(item['offset']))
        constraints[item['prototype']].append(row)
        if item.get('required'):required[item['prototype']].append(row)
    for oid,o in occurrences.items():members[o.prototype].append(oid)
    prototypes={};unresolved={}
    for pid,ids in members.items():
        polygon=_bounded_polygon(tuple(constraints[pid]),tuple(required[pid]),prior)
        if polygon is None:
            for oid in ids:unresolved[oid]='port evidence infeasible for convex adapter'
        else:
            observed=constraints[pid]
            prior_boundary=any(not any(math.dist(normal,n)<1e-7 and abs(bound-b)<1e-7
                for n,b in observed) for normal,bound in wall_evidence(polygon))
            prototypes[pid]=Prototype(pid,polygon,ids,prior_boundary,observed)
    return Inference(occurrences,prototypes,unresolved,prior,graph)


def public_circulation(solution,min_residential_share=.65):
    """Connected public corridor pieces; each remaining room is its own unit.

    Reuse identities/footprints do not change. This is a post-layout assignment
    experiment, not a trained corridor-growth policy or a code-compliance check.
    Only independent realized positive-length contacts may provide openings.
    """
    from shared_modules import contact_pairs
    start=time.perf_counter();_,contacts=contact_pairs(solution)
    adj={nid:set() for nid in solution.graph.nodes}
    for a,b in contacts:adj[a].add(b);adj[b].add(a)
    node_to_occ={n.node_id:oid for oid,o in solution.occurrences.items() for n in o.nodes}
    nodes={n.node_id:n for n in solution.graph.nodes.values() if n.cell_type!=CellType.VOID}
    cores={nid for nid,n in nodes.items() if n.cell_type==CellType.CORE}
    core_occ={node_to_occ[nid] for nid in cores}
    corridor_occ=set(core_occ)
    def public_nodes(assigned):
        return {n.node_id for oid in assigned for n in solution.occurrences[oid].nodes}
    def served(network):
        return network|set().union(*(adj[n] for n in network)) if network else set()
    while True:
        network=public_nodes(corridor_occ);unserved=set(nodes)-served(network)
        if not unserved:break
        frontier={node_to_occ[nid] for nid in served(network)&set(nodes)}-corridor_occ
        options=[]
        for oid in frontier:
            copies=solution.occurrences[oid].nodes
            # A full-height public occurrence must attach on every floor.
            if not all(adj[n.node_id]&network for n in copies):continue
            gain=sum(len(adj[n.node_id]&unserved) for n in copies)
            if gain:options.append((gain/max(1e-9,sum(n.area for n in copies)),oid))
        if not options:break
        corridor_occ.add(max(options)[1])
    def connected(network):
        seen=set(cores);queue=list(cores)
        for current in queue:
            for other in (adj[current]&network)-seen:seen.add(other);queue.append(other)
        return seen==network
    for oid in sorted(corridor_occ-core_occ,reverse=True):
        trial=corridor_occ-{oid};network=public_nodes(trial)
        if connected(network) and set(nodes)<=served(network):corridor_occ=trial
    network=public_nodes(corridor_occ);unserved=set(nodes)-served(network)
    candidate_doors=[];seen=set(cores);queue=list(cores)
    for current in queue:
        for other in sorted((adj[current]&network)-seen):
            seen.add(other);queue.append(other);candidate_doors.append((current,other))
    for nid in sorted(set(nodes)-network):
        available=sorted(adj[nid]&network)
        if available:candidate_doors.append((nid,available[0]))
    reports=[]
    for floor in range(solution.graph.num_floors):
        floor_nodes={nid:n for nid,n in nodes.items() if n.floor_index==floor}
        public_pieces=(network-cores)&set(floor_nodes)
        residential=set(floor_nodes)-network
        total=sum(n.area for n in floor_nodes.values());rentable=sum(nodes[nid].area for nid in residential)
        corridor_area=sum(nodes[nid].area for nid in public_pieces)
        valid=(not (unserved&set(floor_nodes)) and bool(cores&set(floor_nodes))
            and rentable/max(1e-9,total)>=min_residential_share and connected(network))
        reports.append(dict(floor=floor,valid=valid,unserved=sorted(unserved&set(floor_nodes)),corridorOccurrences=len(public_pieces),
            circulationArea=corridor_area,residentialArea=rentable,residentialShare=rentable/max(1e-9,total),
            minimumResidentialShare=min_residential_share,unitCount=len(residential),
            corridors=sorted(public_pieces),units={nid:[nid] for nid in sorted(residential)}))
    return dict(valid=all(r['valid'] for r in reports),perFloor=reports,scopeConflicts=[],
        candidateDoorContacts=candidate_doors,minimumContactLength=solution.prior.min_contact,
        actualDoorDesignVerified=False,
        seconds=time.perf_counter()-start,method='post_layout_connected_public_corridors',trained=False)

